{#- Turns plain multi-line text into tidy HTML: lines starting with "-", "*" or a bullet become
    list items, short label lines followed by more text (e.g. "Key Responsibilities") become
    sub-headings, everything else becomes a paragraph. Rich text (HTML) is passed through. -#}
{%- macro render_text(t) -%}
  {%- if t and ("<p" in t or "<li" in t or "<div" in t or "<br" in t) -%}
    <div class="jo-rich">{{ t }}</div>
  {%- elif t -%}
    {%- set lines = t.replace("\r", "").split("\n") -%}
    {%- set ns2 = namespace(in_list=False, after_heading=False) -%}
    <div class="jo-rich">
    {%- for raw in lines -%}
      {%- set line = raw.strip() -%}
      {%- set nxt = (lines[loop.index].strip() if loop.index < (lines | length) else "") -%}
      {%- set is_heading = line and (line | length) <= 45 and line[-1:] not in [".", ",", ";"] and nxt and line[:1] not in ["-", "*", "•", "–"] -%}
      {%- set is_bullet = line[:1] in ["-", "*", "•", "–"] or (ns2.after_heading and line and not is_heading) -%}
      {%- if not line -%}
        {%- if ns2.in_list -%}</ul>{%- set ns2.in_list = False -%}{%- endif -%}
        {%- set ns2.after_heading = False -%}
      {%- elif is_heading -%}
        {%- if ns2.in_list -%}</ul>{%- set ns2.in_list = False -%}{%- endif -%}
        <h3>{{ line.rstrip(":") | e }}</h3>
        {%- set ns2.after_heading = True -%}
      {%- elif is_bullet -%}
        {%- if not ns2.in_list -%}<ul>{%- set ns2.in_list = True -%}{%- endif -%}
        <li>{{ (line[1:].strip() if line[:1] in ["-", "*", "•", "–"] else line) | e }}</li>
      {%- else -%}
        {%- if ns2.in_list -%}</ul>{%- set ns2.in_list = False -%}{%- endif -%}
        <p>{{ line | e }}</p>
      {%- endif -%}
    {%- endfor -%}
    {%- if ns2.in_list -%}</ul>{%- endif -%}
    </div>
  {%- endif -%}
{%- endmacro -%}

{%- set ns = namespace(row=None) -%}
{%- if doc.job_requisition -%}
  {%- set f = {"parent": doc.job_requisition, "parenttype": "Job Requisition"} -%}
  {%- if doc.custom_role_code -%}{%- set _ = f.update({"role_code": doc.custom_role_code}) -%}{%- elif doc.designation -%}{%- set _ = f.update({"designation": doc.designation}) -%}{%- endif -%}
  {%- set rows = frappe.get_all("Job Requisition Role", filters=f, fields=["custom_function", "custom_sub_function", "scope", "expertise_skillset", "role_description", "experience_required", "no_of_positions", "education"], limit=1) -%}
  {%- if rows -%}{%- set ns.row = rows[0] -%}{%- endif -%}
{%- endif -%}
{%- set row = ns.row or {} -%}
{%- set fn_name = doc.custom_function or row.get("custom_function") -%}
{%- set fn = frappe.db.get_value("Function", fn_name, "function_name") if fn_name else "" -%}
{%- set sfn_name = doc.custom_sub_function or row.get("custom_sub_function") -%}
{%- set sfn = frappe.db.get_value("Function", sfn_name, "function_name") if sfn_name else "" -%}
{%- set experience = doc.custom_experience_required or row.get("experience_required") -%}
{%- set positions = row.get("no_of_positions") or doc.vacancies or doc.planned_vacancies -%}
{%- set experience_text = (experience ~ " years") if experience and (experience | string).strip().isdigit() else experience -%}

{#- Estimate printed lines; if the Role Description would not fit on page 1 under the header,
    start it on page 2. About 100 characters per line at 9.5pt on A4. -#}
{%- set rd = row.get("role_description") or doc.description or "" -%}
{%- set rd_lines = ((rd | striptags) | length) // 100 + rd.count("<li") + rd.count("<p") + rd.count("<br") + rd.count("\n") -%}
{%- set top_text = (row.get("scope") or "") ~ " " ~ (row.get("expertise_skillset") or "") -%}
{%- set top_lines = (top_text | length) // 100 + top_text.count("\n") + 4 -%}
{%- set rd_break = rd_lines > 34 -%}

<div class="jo-page">
  <div class="jo-head">
    <div class="jo-kicker">Position Title</div>
    <h1 class="jo-title">{{ doc.custom_role_classification or doc.job_title }}</h1>
    <div class="jo-sub">
      {%- if doc.custom_role_code %}<span class="jo-code">Position Code: {{ doc.custom_role_code }}</span> &nbsp;&middot;&nbsp; {% endif -%}
      Ref: {{ doc.name }}
    </div>
  </div>

  <table class="jo-facts">
    <tr>
      <td><span class="lbl">Function</span><span class="val">{{ fn or "—" }}</span></td>
      <td><span class="lbl">Sub Function</span><span class="val">{{ sfn or "—" }}</span></td>
      <td><span class="lbl">Experience Required</span><span class="val">{{ experience_text or "—" }}</span></td>
    </tr>
    <tr>
      <td><span class="lbl">Role Shared On</span><span class="val">{{ frappe.utils.formatdate(doc.custom_vendor_push_date) if doc.custom_vendor_push_date else "—" }}</span></td>
      <td><span class="lbl">No. of Positions</span><span class="val">{{ positions or "—" }}</span></td>
      <td><span class="lbl">Location</span><span class="val">{{ doc.custom_country or doc.location or "—" }}</span></td>
    </tr>
  </table>

  <div class="jo-sec{{ ' jo-break' if rd_break else '' }}">
    <h2>Job Description</h2>
    {%- if rd %}
    {{ render_text(rd) }}
    {%- else %}
    <div class="jo-rich"><p>—</p></div>
    {%- endif %}
  </div>

  {%- if row.get("scope") %}
  <div class="jo-sec">
    <h2>Scope</h2>
    {{ render_text(row.get("scope")) }}
  </div>
  {%- endif %}

  {%- if row.get("expertise_skillset") %}
  <div class="jo-sec">
    <h2>Expertise Required</h2>
    {{ render_text(row.get("expertise_skillset")) }}
  </div>
  {%- endif %}

</div>

<div id="footer-html" class="visible-pdf">
  <div style="text-align: center; font-size: 7.5pt; color: #8a94a6; font-family: Arial, Helvetica, sans-serif; letter-spacing: .02em;">
    {{ doc.job_title or doc.name }} &nbsp;&middot;&nbsp; Page <span class="page"></span> of <span class="topage"></span>
  </div>
</div>

css:
/* PDF page margins (applied to every page). Frappe reads these from the plain .print-format rule. */
.print-format {
  margin-top: 18mm;
  margin-bottom: 20mm;
  margin-left: 16mm;
  margin-right: 16mm;
}
/* The element itself gets no margin, so the page margin is not doubled (Frappe ignores this selector). */
.print-format.print-format { margin: 0 !important; }
@media print { .print-format { padding: 0 !important; } }
@media screen { .print-format { padding: 16mm 16mm !important; } }

/* Type scale: title 20pt > section 12.5pt > sub-heading 10pt > body 9.5pt > labels 7.5pt */
.print-format { font-family: Arial, Helvetica, sans-serif; color: #2b3445; font-size: 9.5pt; line-height: 1.5; }
.jo-page { margin: 0; padding: 0; }

.jo-head { border-bottom: 2.5px solid #1f2d50; padding-bottom: 10px; margin-bottom: 16px; }
.jo-company { font-size: 8pt; font-weight: 700; text-transform: uppercase; letter-spacing: .12em; color: #5b6b8c; margin-bottom: 4px; }
.jo-title { font-size: 20pt; line-height: 1.2; font-weight: 700; color: #1f2d50; margin: 0 0 4px; }
.jo-sub { font-size: 8pt; color: #7a8599; }

.jo-facts { width: 100%; border-collapse: collapse; table-layout: fixed; margin: 0 0 20px; }
.jo-facts td { border: 1px solid #e3e8f0; background: #f7f9fc; padding: 8px 11px; vertical-align: top; }
.jo-facts .lbl { display: block; font-size: 7pt; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: #7a8599; margin-bottom: 3px; }
.jo-facts .val { display: block; font-size: 10pt; font-weight: 700; color: #1f2d50; word-wrap: break-word; }

.jo-sec { margin: 0 0 16px; }
.jo-sec h2 { font-size: 12.5pt; font-weight: 700; color: #1f2d50; margin: 0 0 8px; padding: 0 0 5px 9px; border-left: 3.5px solid #1f2d50; border-bottom: 1px solid #e3e8f0; line-height: 1.25; page-break-after: avoid; }

.jo-rich { font-size: 9.5pt; color: #2b3445; word-wrap: break-word; text-align: justify; }
.jo-rich p { margin: 0 0 7px; }
.jo-rich h3 { font-size: 10pt; font-weight: 700; color: #1f2d50; margin: 10px 0 4px; page-break-after: avoid; }
.jo-rich ul, .jo-rich ol { margin: 2px 0 9px; padding-left: 18px; }
.jo-rich li { margin: 0 0 3px; padding-left: 2px; text-align: left; }
.jo-rich p, .jo-rich li { page-break-inside: avoid; }
.jo-rich strong, .jo-rich b { color: #1f2d50; }

.jo-break { page-break-before: always; break-before: page; }
@media screen { .jo-break { border-top: 1px dashed #cbd5e1; margin-top: 22px; padding-top: 16px; } }

.jo-kicker { font-size: 7.5pt; font-weight: 700; text-transform: uppercase; letter-spacing: .12em; color: #7a8599; margin: 6px 0 1px; }
.jo-code { font-weight: 700; color: #1f2d50; }

